import 'dart:io';import 'package:udara_cli/core/core.dart';import 'package:udara_cli/services/config_service.dart';import 'package:udara_cli/services/slack_service.dart';class SlackTestCommand extends UdaraCommand {  SlackTestCommand() {    argParser.addOption(      'channel',      abbr: 'c',      help: 'Channel to test (e.g., #general, @username)',      defaultsTo: '#general',    );  }  @override  final String name = 'slack-test';  @override  final String description = 'Test Slack integration and debug connection issues.';  @override  Future<void> run() async {    final channel = argResults!['channel'] as String;    print('🧪 Testing Slack Integration');    print('═' * 50);    // Check if Slack is configured    final slackToken = await ConfigService.getSlackBotToken();    if (slackToken == null) {      print('❌ Slack not configured.');      print('💡 Run "udara_cli setup" to configure Slack first.');      return;    }    print('✅ Slack token found');    print('🎯 Target channel: $channel');    print('');    // Create service with debug mode    final slackService = SlackService(      botToken: slackToken,      channel: channel,      debugMode: true,    );    // Test 1: Authentication    print('🔐 Testing authentication...');    final authSuccess = await slackService.testConnection();    if (!authSuccess) {      print('❌ Authentication failed. Check your bot token.');      return;    }    print('✅ Authentication successful\n');    // Test 2: Simple message    print('📝 Sending test message...');    final messageSuccess = await slackService.sendMessage(      '🧪 Test message from Udara CLI at ${DateTime.now()}',      emoji: ':robot_face:',    );    if (messageSuccess) {      print('✅ Simple message sent successfully\n');    } else {      print('❌ Failed to send simple message\n');      _printTroubleshootingTips(channel);      return;    }    // Test 3: Rich message    print('🎨 Sending rich message...');    final richSuccess = await slackService.sendRichMessage(      title: '🧪 Rich Message Test',      message: 'This is a test of rich message formatting',      color: 'good',      fields: {        'Test Type': 'Rich Message',        'Status': 'Testing',        'Timestamp': DateTime.now().toString(),      },    );    if (richSuccess) {      print('✅ Rich message sent successfully\n');    } else {      print('❌ Failed to send rich message\n');    }    // Test 4: Build notification simulation    print('🚀 Simulating build notification...');    await slackService.sendBuildStepNotification(      step: 'Test Build Step',      client: 'test-client',      platform: 'android',      status: 'completed',      additionalInfo: 'This is a test notification',    );    print('');    print('🎉 Slack test completed!');    print('💡 If you received messages in $channel, Slack integration is working correctly.');  }  void _printTroubleshootingTips(String channel) {    print('🔧 Troubleshooting Tips:');    print('');    print('1. Channel Issues:');    print('   • Make sure channel "$channel" exists');    print('   • Add your bot to the channel first');    print('   • For private channels, use channel ID instead of name');    print('');    print('2. Bot Permissions:');    print('   • Go to https://api.slack.com/apps');    print('   • Select your app → OAuth & Permissions');    print('   • Ensure these scopes are added:');    print('     - chat:write');    print('     - files:write');    print('     - channels:read');    print('');    print('3. Bot Installation:');    print('   • Make sure the bot is installed in your workspace');    print('   • Check if the bot token starts with "xoxb-"');    print('');    print('4. Channel Access:');    print('   • In Slack, go to the channel');    print('   • Type @your-bot-name to invite it');    print('   • Or use /invite @your-bot-name');  }}